```typescript
async function traceExecution(
  executionId: string,
  templateId: string,
  variantId: string | null,
  activityId: string,
  status: 'success' | 'failed' | 'timeout',
  durationMs: number,
  cost: number,
  success: boolean,
  tasks: any[],
  impulsesUsed: string[],
  stateSnapshot: any,
  errorMessage?: string
): Promise<void> {
  try {
    const payload = {
      execution_id: executionId,
      template_id: templateId,
      variant_id: variantId || templateId,
      activity_id: activityId,
      status,
      duration_ms: durationMs,
      cost_usd: cost,  // Note: backend expects cost_usd not cost
      success,
      tasks: tasks.map(t => ({
        task_id: t.id || 'unknown',
        description: t.description || '',
        status: t.status || 'unknown',
        duration_ms: t.duration_ms || 0,
        tool_calls: t.tool_calls || []
      })),
      impulses_used: impulsesUsed,
      state_snapshot: stateSnapshot,
      error_message: errorMessage || null
    };

    const backendUrl = process.env.BACKEND_URL || 'http://localhost:8081';
    const response = await fetch(`${backendUrl}/v2/activities/execution-traces`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      console.error('Failed to store execution trace:', response.status, await response.text());
      return; // Don't fail activity if trace storage fails
    }

    const result = await response.json();
    console.log('✅ Execution trace stored:', result.trace_id);
  } catch (error) {
    console.error('Error storing execution trace:', error);
    // Don't throw - trace storage failure should not fail the activity
  }
}
```

